<script type="text/javascript">
jQuery(document).ready(function()
{
   jQuery('.linktocom').on( "click", function(event)
   {
      event.preventDefault();

      javascript:jQuery.LoadingStructData();
      var $elemento = jQuery(this);

      jQuery.ajax({      
            method: 'POST',              
            url: '<?php echo url_for('com_enviada/updateComrecibidaRespuesta');?>',         
            data: jQuery.param({ comenviada_id : <?php echo $comenviada_id; ?>, comrecibida_id : jQuery(this).data('comrecibida_id') }) ,
            success: function(response)
            {
               if(response.status == 200)
               {
                  toastr.success(response.mensaje);
                  toastr.info("La informacion se actualizara en un momento, espere por favor");
                  setTimeout(function() { parent.jQuery.CloseModalSIMAD(); }, 5000)
               }
               else if(response.status == 300)
               {
                  javascript:jQuery.CloseLoadingStructData();
                  toastr.warning(response.mensaje); 
               }
               else if(response.status == 400)
               {
                  javascript:jQuery.CloseLoadingStructData();
                  toastr.error(response.mensaje); 
               }
               else if(response.status == 401)
               {
                  javascript:jQuery.CloseLoadingStructData();
                  toastr.error(response.mensaje);
                  $elemento.closest('.custopenlinkto').find(".archivedoc").remove();
                  $elemento.closest('.custopenlinkto').append(response.url_linkto);
               }
               else
               {
                  javascript:jQuery.CloseLoadingStructData();  
                  toastr.error("Error Interno del Servidor!");
               }
               
            },
            error: function(jqXHR, textStatus, errorThrown) 
            {
               if (jqXHR.status == 404) 
               {
                  javascript:jQuery.CloseLoadingStructData();  
                  toastr.error("Error Interno del Servidor!");
               }
            }
      });
   });
});
</script>